	/* @Test */
	public void testLocalGdbSetup()
    {
		pipOob("protobuf==3.19.0");
		using (LaunchResult result = doLaunch("gdb", Map.of("arg:1", chooseImage())))
{
			assertTrue(result.exception() is EarlyTerminationException);
			assertThat(result.sessions().get("Shell").content(),
				Matchers.containsString("Would you like to install"));
		}
		using (LaunchResult result = doLaunch("gdb", Map.of("arg:1", chooseImage())))
{
			checkResult(result);
		}
	}

